"use client";

/**
 * アプリの骨組み。どの画面もこの中に入る。
 *   767px 以下   … 下タブ（BottomTabBar）
 *   768〜1279px  … アイコン列（SideNav）
 *   1280px 以上  … サイドバー（SideNav・畳める）
 * どの画面からでも使うもの（追加・⌘K パレット・キーボードの近道）は、ここで1つだけ持つ。
 * アプリごとの中身（名前・追加シート・⌘K の候補・外側の入れ物）は config/shell.tsx から受け取る。このファイルは書き換えない。
 *
 * キーボードの近道（文字を入力中・シートやダイアログが開いている間は効かない）
 *   ⌘K / Ctrl+K / 「/」 … 検索・操作
 *   N                    … 追加（config/shell.tsx の AddSheet があるとき）
 *   1〜9                 … ナビの1〜9番目へ移動
 */
import { useRouter } from "next/navigation";
import { createContext, useContext, useEffect, useRef, useState } from "react";
import { NAV } from "@/config/nav";
import { AddSheet, ShellProviders } from "@/config/shell";
import { Toaster } from "@/components/kit/toast";
import { BottomTabBar } from "./bottom-tab-bar";
import { CommandPalette } from "./command-palette";
import { SideNav } from "./side-nav";
import { ThemeFonts } from "./theme-fonts";

const ShellCtx = createContext<{ openAdd: () => void; openSearch: () => void }>({ openAdd: () => {}, openSearch: () => {} });
export const useShell = () => useContext(ShellCtx);

const typing = (el: EventTarget | null) => el instanceof HTMLElement && (el.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName));
const overlayOpen = () => !!document.querySelector('[role="dialog"],[role="alertdialog"],[role="menu"]');

export function AppFrame({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const [adding, setAdding] = useState(false);
  const [searching, setSearching] = useState(false);
  const searchingRef = useRef(searching);
  useEffect(() => {
    searchingRef.current = searching;
  }, [searching]);
  const openAdd = () => setAdding(true);
  const openSearch = () => setSearching(true);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.isComposing) return;
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
        // シートやメニューが開いている間は奪わない（重なって開き、打った文字が後ろのシートに入るため）。パレット自身を閉じるのは可
        if (!searchingRef.current && overlayOpen()) return;
        e.preventDefault();
        setSearching((s) => !s);
        return;
      }
      if (e.metaKey || e.ctrlKey || e.altKey || typing(e.target) || overlayOpen()) return;
      if (e.key === "/") {
        e.preventDefault();
        setSearching(true);
      } else if (AddSheet && (e.key === "n" || e.key === "N")) {
        e.preventDefault();
        setAdding(true);
      } else if (/^[1-9]$/.test(e.key) && NAV[Number(e.key) - 1]) {
        router.push(NAV[Number(e.key) - 1].href);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [router]);

  return (
    <ShellProviders>
      <ShellCtx.Provider value={{ openAdd, openSearch }}>
        <a href="#main" className="sr-only focus:not-sr-only focus:fixed focus:top-2 focus:left-2 focus:z-50 focus:rounded-md focus:bg-surface focus:px-3 focus:py-2">
          本文へ移動
        </a>
        <div aria-hidden className="wk-ambient" />
        <SideNav onAdd={AddSheet ? openAdd : undefined} onSearch={openSearch} />
        <div className="wk-content">
          <main id="main">{children}</main>
        </div>
        <BottomTabBar />
        {AddSheet && <AddSheet open={adding} onOpenChange={setAdding} />}
        <CommandPalette open={searching} onOpenChange={setSearching} onAdd={AddSheet ? openAdd : undefined} />
        <Toaster />
        <ThemeFonts />
      </ShellCtx.Provider>
    </ShellProviders>
  );
}

"use client";

/**
 * スマホの下タブ（767px 以下だけ表示）。見た目と動きは iOS 26 の下タブ（Liquid Glass）に合わせている。
 * ガラスの仕組みは components/kit/liquid-glass（元は @zakisheriff/liquid-glass・MIT）。
 *
 *   止まっているとき … 選んだタブはアイコンが塗りつぶし＋文字が主色。下にバーより少し灰色の薄い玉
 *   指が触れた瞬間   … 押したタブが選択表示になり、玉が持ち上がって澄んだ泡のレンズになる（下のアイコンを拡大して塗る）
 *   押さえたまま横になぞる … レンズが指についてくる。速く動かすと伸び、止まるとぷるんと揺れる
 *   指を離した瞬間   … 画面を切り替える（中身はフェードも横すべりもしない＝即移動）。レンズは揺れながら収まる
 *   動きを減らす設定 … バネを使わず、すぐ収まる
 *   項目が6つ以上（またはログイン中の人の欄がある）とき … 先頭4つ＋「もっと」。「もっと」は残りの項目とアカウント欄を下からのシートで出す
 *
 * 画面の切り替えは <Link> の先読み（App Shell）が効いているので、押してから待たない。
 * 今の場所（usePathname）は <Suspense> の中で読む。[id] のような動く住所の画面でも事前の描画が止まらないように、
 * 読めるまでは選択表示の無い同じバーを出す。
 */
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { Suspense, useState } from "react";
import { Ellipsis } from "lucide-react";
import { NAV, isActive } from "@/config/nav";
import { useAccount } from "@/config/shell";
import { Sheet } from "@/components/kit/sheet";
import { LensTrack } from "@/components/kit/liquid-glass/lens-track";
import { cn } from "@/lib/cn";

const MORE = { href: "#more", label: "もっと", short: "もっと", icon: Ellipsis };

export function BottomTabBar() {
  const account = useAccount();
  if (NAV.length === 0 && !account) return null;
  return (
    <Suspense fallback={<TabBar pathname={null} account={account} />}>
      <TabBarAtPath account={account} />
    </Suspense>
  );
}

function TabBarAtPath({ account }: { account: ReturnType<typeof useAccount> }) {
  return <TabBar pathname={usePathname()} account={account} />;
}

function TabBar({ pathname: at, account }: { pathname: string | null; account: ReturnType<typeof useAccount> }) {
  const pathname = at ?? "";
  const needsMore = NAV.length > 5 || !!account;
  const tabs = NAV.slice(0, needsMore ? 4 : 5);
  const rest = NAV.slice(tabs.length);
  const items = needsMore ? [...tabs, MORE] : tabs;
  const [moreOpen, setMoreOpen] = useState(false);
  const router = useRouter();

  // 押した瞬間に選択表示にするための「仮の選択」。画面が移り終わったら実際の場所に従う
  // どのナビにも無い画面（と、場所がまだ分からない間）は -1＝どれも選ばない
  const tabIndex = at === null ? -1 : tabs.findIndex((i) => isActive(pathname, i.href));
  const routeIndex = tabIndex >= 0 ? tabIndex : at !== null && needsMore && rest.some((i) => isActive(pathname, i.href)) ? tabs.length : -1;
  const [pressed, setPressed] = useState<{ index: number; from: string } | null>(null);
  // 場所が変わったら（移り終わった・戻る/進む）仮の選択を捨てる
  const [seenPath, setSeenPath] = useState(pathname);
  if (seenPath !== pathname) {
    setSeenPath(pathname);
    setPressed(null);
  }
  const active = pressed && pressed.from === pathname ? pressed.index : routeIndex;

  // 離した瞬間（キーボードの Enter もここに来る）
  const go = (index: number) => {
    const href = items[index].href;
    setPressed({ index, from: pathname });
    if (href === MORE.href) {
      setMoreOpen(true);
      return;
    }
    if (!isActive(pathname, href)) router.push(href);
  };

  return (
    <>
      <nav
        aria-label="メインメニュー"
        data-nav="tabbar"
        className="fixed inset-x-5 z-40 mx-auto max-w-[520px] select-none rail:hidden"
        style={{
          bottom: "calc(var(--wk-tabbar-gap) + var(--wk-safe-b))",
          height: "var(--wk-tabbar-h)",
        }}
      >
        <LensTrack
          count={items.length}
          index={active}
          onPress={(index) => setPressed({ index, from: pathname })}
          onSelect={go}
          renderItem={(i, props) => {
            const item = items[i];
            const on = i === active;
            const Icon = item.icon;
            const inner = (
              <>
                <span className="lg-nav__icons" aria-hidden>
                  <span className="lg-nav__icon lg-nav__icon--idle">
                    <Icon size={24} strokeWidth={1.8} />
                  </span>
                  <span className="lg-nav__icon lg-nav__icon--active">
                    {/* 選んだ形：中を塗りつぶす（iOS の下タブと同じ） */}
                    <Icon size={24} strokeWidth={2.1} fill="currentColor" fillOpacity={0.9} />
                  </span>
                </span>
                <span className={cn("lg-nav__label", on && "font-semibold")}>{item.short}</span>
              </>
            );
            if (item.href === MORE.href) {
              return (
                <button
                  {...props}
                  type="button"
                  aria-haspopup="dialog"
                  aria-expanded={moreOpen}
                  aria-current={i === routeIndex && tabIndex < 0 ? "page" : undefined}
                  data-on={on ? "1" : "0"}
                >
                  {inner}
                </button>
              );
            }
            return (
              <Link
                {...props}
                href={item.href}
                aria-current={isActive(pathname, item.href) ? "page" : undefined}
                // 移動は上の onSelect（離した瞬間・Enter）で行う。リンクとしての移動は止める（二重に動かないように）
                onClick={(e) => e.preventDefault()}
                draggable={false}
                data-on={on ? "1" : "0"}
              >
                {inner}
              </Link>
            );
          }}
        />
      </nav>
      {needsMore && (
        <Sheet
          open={moreOpen}
          onOpenChange={(open) => {
            setMoreOpen(open);
            // 何も選ばずに閉じたら、玉を今いる場所へ戻す
            if (!open) setPressed(null);
          }}
          title="メニュー"
        >
          <MoreList
            rest={rest}
            pathname={pathname}
            account={account}
            onPick={(run, navigates) => {
              setMoreOpen(false);
              // 画面が移らない操作（ログアウト前の確認・明るさの切り替えなど）は、玉を今いる場所へ戻す
              if (!navigates) setPressed(null);
              run();
            }}
          />
        </Sheet>
      )}
    </>
  );
}

/** 「もっと」の中身：下タブに入らなかった項目と、ログイン中の人の欄 */
function MoreList({
  rest,
  pathname,
  account,
  onPick,
}: {
  rest: typeof NAV;
  pathname: string;
  account: ReturnType<typeof useAccount>;
  onPick: (run: () => void, navigates: boolean) => void;
}) {
  const router = useRouter();
  const row = "flex min-h-row w-full items-center gap-3 rounded-md px-3 text-left transition-colors active:bg-surface-2";
  return (
    <div className="grid gap-4">
      {rest.length > 0 && (
        <ul className="grid gap-0.5">
          {rest.map((item) => {
            const on = isActive(pathname, item.href);
            const Icon = item.icon;
            return (
              <li key={item.href}>
                <Link
                  href={item.href}
                  aria-current={on ? "page" : undefined}
                  onClick={(e) => {
                    e.preventDefault();
                    onPick(() => router.push(item.href), true);
                  }}
                  className={cn(row, on ? "bg-accent-soft font-medium text-accent-text" : "text-fg hover:bg-surface-2")}
                >
                  <Icon aria-hidden size={20} className="flex-none text-current" />
                  {item.label}
                </Link>
              </li>
            );
          })}
        </ul>
      )}
      {account && (
        <div className="grid gap-0.5 border-t border-line pt-3">
          <p className="truncate px-3 pb-1 text-sm text-fg-3">{account.name}</p>
          {account.actions.map((a) => (
            <button key={a.id} type="button" onClick={() => onPick(a.run, false)} className={cn(row, "text-fg hover:bg-surface-2")}>
              <a.icon aria-hidden size={20} className="flex-none" />
              {a.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/*
 * テーマ・明るさ・密度・サイドバーの開閉を、描画の前に <html> へ反映する（ちらつき防止）。
 * 保存先はこのブラウザだけ（localStorage）。読めなくても既定値で正しく表示される。
 * テーマの優先順：URL の ?palette=…（見本サイトの並べ比べ用。覚えさせない）→ この端末で選んだテーマ → アプリの既定テーマ
 */
import { PALETTES } from "@/lib/palettes";

/** 常に暗い専用のテーマ。明るさをライトに固定したアプリでは選ばせない */
const DARK_ONLY = PALETTES.filter((p) => p.darkOnly).map((p) => p.id);

export function bootScript(defaultPalette = "graphite", forceTheme?: "light" | "dark") {
  const def = JSON.stringify(/^[a-z0-9-]+$/.test(defaultPalette) ? defaultPalette : "graphite");
  // 明るさを固定するアプリ（ダーク未対応の画面が残っている後付けなど）は、保存された明るさより優先し、切り替えの操作も隠す
  const lock =
    forceTheme === "light" || forceTheme === "dark"
      ? `d.dataset.theme="${forceTheme}";d.dataset.themeLocked="1";` +
        (forceTheme === "light" ? `if(${JSON.stringify(DARK_ONLY)}.indexOf(d.dataset.palette)>=0)delete d.dataset.palette;` : "")
      : "";
  return `try{var d=document.documentElement,q=new URLSearchParams(location.search),v=${def},p=q.get("palette"),ok=/^[a-z0-9-]+$/;try{var x=localStorage.getItem("wk.palette");if(x&&ok.test(x))v=x}catch(e){}if(p&&ok.test(p))v=p;if(v!=="graphite")d.dataset.palette=v;var m=q.get("theme");if(m==="light"||m==="dark")d.dataset.theme=m;${lock}}catch(e){}try{var d=document.documentElement,s=localStorage;var t=s.getItem("wk.theme");if(!d.dataset.theme&&(t==="light"||t==="dark"))d.dataset.theme=t;var n=s.getItem("wk.density");if(n==="compact")d.dataset.density=n;if(s.getItem("wk.sidebar")==="collapsed")d.dataset.sidebar="collapsed"}catch(e){}`;
}

/**
 * ルートの layout の <head> の中に置く。既存のアプリに入れるときも、これを1行足すだけでよい。
 * defaultPalette … このアプリの既定のテーマ（例："sky"）。使う人が設定や ⌘K で選ぶと、その端末ではそちらが優先される
 * forceTheme     … 明るさを固定する（"light" か "dark"）。ダーク表示に対応していない画面が残っているうちに使う
 */
export function WorkspaceBoot({ defaultPalette = "graphite", forceTheme }: { defaultPalette?: string; forceTheme?: "light" | "dark" }) {
  return <script dangerouslySetInnerHTML={{ __html: bootScript(defaultPalette, forceTheme) }} />;
}

"use client";

/**
 * ⌘K パレット（検索と操作の入口）。⌘K / Ctrl+K・「/」・サイドバーの「検索・操作」・一覧の「検索」で開く。
 *   文字を打つと、操作とアプリの中身（config/shell.tsx の useExtraCommands）を同時に絞り込む。↑↓ で選んで Enter、esc で閉じる。
 * 操作を増やすときは commands の配列に、アプリの中身は useExtraCommands に足す（group が見出しになる）。
 */
import { Dialog } from "@base-ui/react/dialog";
import { CornerDownLeft, Monitor, Moon, Palette, Plus, Rows3, Search, Sun, type LucideIcon } from "lucide-react";
import { useRouter } from "next/navigation";
import { useId, useState } from "react";
import { NAV } from "@/config/nav";
import { PALETTES } from "@/lib/palettes";
import { setDensity, setPalette, setTheme, themeLocked } from "@/lib/prefs";
import { APP, AddSheet, useAccount, useExtraCommands } from "@/config/shell";
import { cn } from "@/lib/cn";

/** ナビの一番下（スマホは「もっと」の中）と ⌘K に出す、ログイン中の人と操作 */
export type AccountInfo = { name: string; actions: { id: string; label: string; icon: LucideIcon; run: () => void }[] };

export type PaletteItem = { id: string; group: string; label: string; hint?: string; icon: LucideIcon; keywords?: string; run: () => void };

export function CommandPalette({ open, onOpenChange, onAdd }: { open: boolean; onOpenChange: (open: boolean) => void; onAdd?: () => void }) {
  return (
    <Dialog.Root open={open} onOpenChange={onOpenChange}>
      <Dialog.Portal>
        {/* 出し入れの動きは付けない。キーボードで1日に何十回も開くので、押した瞬間に出て、すぐ消える方が速く感じる */}
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-scrim" />
        <Dialog.Popup className="fixed top-[max(12px,env(safe-area-inset-top,0px))] left-1/2 z-50 flex max-h-[min(560px,calc(100dvh-24px))] w-[min(600px,calc(100vw-24px))] -translate-x-1/2 flex-col wk-glass-sheet overflow-hidden rounded-lg outline-none rail:top-[12vh]">
          <Dialog.Title className="sr-only">検索・操作</Dialog.Title>
          <Body
            onRun={(run) => {
              onOpenChange(false);
              // 閉じてから実行する（次に開くシートとフォーカスを取り合わないように）
              setTimeout(run, 0);
            }}
            onAdd={onAdd}
          />
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function Body({ onRun, onAdd }: { onRun: (run: () => void) => void; onAdd?: () => void }) {
  const router = useRouter();
  const [q, setQ] = useState("");
  const needle = q.trim().toLowerCase();
  const extra = useExtraCommands(needle);
  const account = useAccount();
  const [active, setActive] = useState(0);
  const listId = useId();

  const commands: PaletteItem[] = [
    ...(AddSheet && onAdd ? [{ id: "add", group: "操作", label: APP.addLabel, hint: "N", icon: Plus, keywords: "新規 つくる 追加", run: onAdd }] : []),
    ...NAV.map((n, i) => ({ id: `go-${n.href}`, group: "移動", label: `${n.label}を開く`, hint: String(i + 1), icon: n.icon, run: () => router.push(n.href) })),
    // 明るさを固定しているアプリ（WorkspaceBoot の forceTheme）では、明るさの切り替えを出さない
    ...(themeLocked() ? [] : [
    { id: "light", group: "見た目", label: "明るさ：ライト", icon: Sun, keywords: "テーマ 白", run: () => setTheme("light") },
    { id: "dark", group: "見た目", label: "明るさ：ダーク", icon: Moon, keywords: "テーマ 黒 夜", run: () => setTheme("dark") },
    { id: "system", group: "見た目", label: "明るさ：端末に合わせる", icon: Monitor, keywords: "テーマ 自動", run: () => setTheme("system") },
    ]),
    { id: "compact", group: "見た目", label: "行の高さ：詰める", icon: Rows3, keywords: "密度", run: () => setDensity("compact") },
    { id: "comfy", group: "見た目", label: "行の高さ：ゆったり", icon: Rows3, keywords: "密度", run: () => setDensity("comfy") },
    ...(account?.actions.map((a) => ({ id: `account-${a.id}`, group: "アカウント", label: a.label, hint: account.name, icon: a.icon, run: a.run })) ?? []),
    // 明るさを固定しているときは、常に暗い専用のテーマ（ナイトなど）を出さない
    ...PALETTES.filter((p) => !(p.darkOnly && themeLocked())).map((p) => ({ id: `palette-${p.id}`, group: "テーマ", label: `テーマ：${p.label}`, icon: Palette, keywords: `色 ${p.desc}`, run: () => setPalette(p.id) })),
  ];

  const hit = (s: string) => s.toLowerCase().includes(needle);
  const items = [...commands.filter((c) => !needle || hit(c.label) || hit(c.keywords ?? "")), ...extra];
  const cur = Math.min(active, Math.max(0, items.length - 1));
  const optionId = (i: number) => `${listId}-${i}`;

  const groups: { name: string; rows: { item: PaletteItem; index: number }[] }[] = [];
  items.forEach((item, index) => {
    const g = groups.find((x) => x.name === item.group) ?? groups[groups.push({ name: item.group, rows: [] }) - 1];
    g.rows.push({ item, index });
  });

  return (
    <>
      <div className="flex flex-none items-center gap-2.5 border-b border-line px-4">
        <Search aria-hidden size={18} className="flex-none text-fg-3" />
        <input
          autoFocus
          role="combobox"
          aria-expanded="true"
          aria-controls={listId}
          aria-activedescendant={items.length ? optionId(cur) : undefined}
          aria-label={APP.searchLabel}
          placeholder={APP.searchLabel}
          value={q}
          onChange={(e) => {
            setQ(e.target.value);
            setActive(0);
          }}
          onKeyDown={(e) => {
            if (e.nativeEvent.isComposing) return;
            if (e.key === "ArrowDown" || e.key === "ArrowUp") {
              e.preventDefault();
              const n = items.length;
              if (n) setActive((cur + (e.key === "ArrowDown" ? 1 : n - 1)) % n);
            } else if (e.key === "Enter" && items[cur]) {
              e.preventDefault();
              onRun(items[cur].run);
            }
          }}
          className="h-14 min-w-0 flex-1 bg-transparent outline-none placeholder:text-fg-3 focus-visible:outline-none"
          autoComplete="off"
          enterKeyHint="go"
        />
        <Dialog.Close className="h-hit flex-none rounded-sm px-2 text-xs text-fg-3 hover:bg-surface-2 hover:text-fg">
          <span className="pointer-coarse:hidden">esc</span>
          <span className="hidden pointer-coarse:inline">閉じる</span>
        </Dialog.Close>
      </div>

      <div id={listId} role="listbox" aria-label="候補" className="min-h-0 flex-1 overflow-y-auto overscroll-contain p-1.5">
        {items.length ? (
          groups.map((g) => (
            <div key={g.name} role="group" aria-label={g.name}>
              <div aria-hidden className="px-2.5 pt-2.5 pb-1 text-xs text-fg-3">
                {g.name}
              </div>
              {g.rows.map(({ item, index }) => (
                <div
                  key={item.id}
                  id={optionId(index)}
                  role="option"
                  aria-selected={index === cur}
                  onPointerMove={() => index !== cur && setActive(index)}
                  onClick={() => onRun(item.run)}
                  // 選んでいる行は、地の色に加えて左に主色の線を出す（地の色の差だけでは見分けにくい）
                  className={cn("flex min-h-hit cursor-pointer items-center gap-3 rounded-md px-2.5 py-1.5 text-sm", index === cur && "bg-surface-2 shadow-[inset_2px_0_0_var(--wk-accent)]")}
                >
                  <item.icon aria-hidden size={16} className="flex-none text-fg-3" />
                  <span className="min-w-0 flex-1 truncate">{item.label}</span>
                  {item.hint && <span className="flex-none text-xs text-fg-3">{item.hint}</span>}
                  {index === cur && <CornerDownLeft aria-hidden size={14} className="flex-none text-fg-3 pointer-coarse:hidden" />}
                </div>
              ))}
            </div>
          ))
        ) : (
          <p className="px-3 py-8 text-center text-sm text-fg-3">「{q}」に合うものはありません</p>
        )}
      </div>

      <div aria-hidden className="flex flex-none gap-4 border-t border-line px-4 py-2 text-xs text-fg-3 pointer-coarse:hidden">
        <span>↑↓ 選ぶ</span>
        <span>Enter 実行</span>
        <span>esc 閉じる</span>
      </div>
    </>
  );
}

"use client";

/**
 * PC・タブレットのナビ。768〜1279px はアイコン列、1280px 以上はサイドバー（畳むとアイコン列）。
 * 項目と順番は下タブと同じ（config/nav.ts）。押した瞬間に選択表示を移し、画面の切り替えは待たせない。
 * 画面の切り替えは1日に何十回もするので、選択の下地は動かさずにその場で入れ替える。
 * 今の場所（usePathname）は <Suspense> の中で読む（動く住所の画面でも事前の描画を止めない）。読めるまでは選択表示の無い同じナビを出す。
 * 項目が多いときは、項目の部分だけが縦にスクロールする（項目を押しつぶさない）。
 */
import Link from "next/link";
import { usePathname } from "next/navigation";
import { PanelLeftClose, PanelLeftOpen, Plus, Search } from "lucide-react";
import { Suspense, useState } from "react";
import { NAV, isActive } from "@/config/nav";
import { APP, useAccount } from "@/config/shell";
import { cn } from "@/lib/cn";

function setCollapsed(collapsed: boolean) {
  const d = document.documentElement;
  if (collapsed) d.dataset.sidebar = "collapsed";
  else delete d.dataset.sidebar;
  try {
    localStorage.setItem("wk.sidebar", collapsed ? "collapsed" : "open");
  } catch {}
}

const itemClass =
  "flex h-11 w-full flex-none items-center gap-3 rounded-md px-3 text-sm whitespace-nowrap transition-colors duration-[var(--wk-dur-fast)] " +
  "max-side:justify-center max-side:px-0 [:root[data-sidebar=collapsed]_&]:justify-center [:root[data-sidebar=collapsed]_&]:px-0";

type Props = { onSearch?: () => void; onAdd?: () => void };

export function SideNav(props: Props) {
  return (
    <Suspense fallback={<Side {...props} pathname={null} />}>
      <SideAtPath {...props} />
    </Suspense>
  );
}

function SideAtPath(props: Props) {
  return <Side {...props} pathname={usePathname()} />;
}

function Side({ onSearch, onAdd, pathname: at }: Props & { pathname: string | null }) {
  const pathname = at ?? "";
  const account = useAccount();
  const [pressed, setPressed] = useState<{ href: string; from: string } | null>(null);
  const [seenPath, setSeenPath] = useState(pathname);
  if (seenPath !== pathname) {
    setSeenPath(pathname);
    setPressed(null);
  }
  const current = pressed && pressed.from === pathname ? pressed.href : null;

  return (
    <nav
      aria-label="メインメニュー"
      data-nav="side"
      className="fixed inset-y-0 left-0 z-30 hidden flex-col gap-1 wk-glass-side overflow-hidden py-4 pr-3 rail:flex"
      style={{
        width: "var(--wk-nav-w)",
        // 横向きの iPhone では切り欠きの分だけ内側に寄せる
        paddingLeft: "max(0.75rem, env(safe-area-inset-left, 0px))",
        // 幅は動かさない（width を動かすと本文の配置計算が毎コマ走り、窓幅を変えたときも本文が遅れてついてくる）
      }}
    >
      <div className="mb-3 flex items-center gap-2.5 px-1.5 max-side:justify-center max-side:px-0 [:root[data-sidebar=collapsed]_&]:justify-center [:root[data-sidebar=collapsed]_&]:px-0">
        <span className="grid size-8 flex-none place-items-center rounded-lg bg-accent text-sm font-semibold text-on-accent">{APP.mark}</span>
        <span className="wk-nav-label truncate text-sm font-semibold">{APP.name}</span>
      </div>

      {onSearch && (
        <button type="button" onClick={onSearch} title="検索・操作（⌘K）" className={cn(itemClass, "mb-2 border border-line bg-surface text-fg-2 hover:text-fg active:bg-surface-2")}>
          <Search aria-hidden size={18} className="flex-none" />
          <span className="wk-nav-label">検索・操作</span>
          <kbd className="wk-nav-label ml-auto rounded border border-line px-1.5 font-sans text-xs text-fg-3">⌘K</kbd>
        </button>
      )}

      <div className="-mx-1 grid min-h-0 flex-1 content-start gap-1 overflow-y-auto px-1">
      {NAV.map((item) => {
        const on = current ? current === item.href : at !== null && isActive(pathname, item.href);
        const Icon = item.icon;
        return (
          <Link
            key={item.href}
            href={item.href}
            title={item.label}
            aria-current={at !== null && isActive(pathname, item.href) ? "page" : undefined}
            onPointerDown={(e) => {
              // 右クリック・新しいタブで開く（⌘・Ctrl・Shift）は、この画面の選択を変えない
              if (e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
              setPressed({ href: item.href, from: pathname });
            }}
            // 押したまま外へずらして離したら、仮の選択を捨てる
            onPointerCancel={() => setPressed(null)}
            onPointerLeave={(e) => {
              if (e.buttons) setPressed(null);
            }}
            className={cn(itemClass, on ? "bg-accent-soft font-medium text-accent-text" : "text-fg-2 hover:bg-surface-2 hover:text-fg")}
          >
            <Icon aria-hidden size={20} strokeWidth={on ? 2.2 : 1.8} className="flex-none" />
            <span className="wk-nav-label">{item.label}</span>
          </Link>
        );
      })}
      </div>

      {onAdd && (
        <button type="button" onClick={onAdd} title={APP.addLabel} className={cn(itemClass, "text-fg-2 hover:bg-surface-2 hover:text-fg active:bg-surface-2")}>
          <Plus aria-hidden size={20} className="flex-none" />
          <span className="wk-nav-label">{APP.addLabel}</span>
        </button>
      )}
      {account && (
        <div className="mt-1 grid gap-1 border-t border-line pt-2">
          <p className="wk-nav-wide px-3 text-xs text-fg-3" title={account.name}>
            <span className="min-w-0 truncate">{account.name}</span>
          </p>
          {account.actions.map((a) => (
            <button key={a.id} type="button" onClick={a.run} title={a.label} className={cn(itemClass, "text-fg-2 hover:bg-surface-2 hover:text-fg active:bg-surface-2")}>
              <a.icon aria-hidden size={20} className="flex-none" />
              <span className="wk-nav-label">{a.label}</span>
            </button>
          ))}
        </div>
      )}
      {/* 畳む・広げる（1280px 以上のときだけ） */}
      <button
        type="button"
        onClick={() => setCollapsed(document.documentElement.dataset.sidebar !== "collapsed")}
        className={cn(itemClass, "hidden text-fg-3 hover:bg-surface-2 hover:text-fg side:flex")}
        title="サイドバーを畳む・広げる"
      >
        <PanelLeftClose aria-hidden size={20} className="flex-none [:root[data-sidebar=collapsed]_&]:hidden" />
        <PanelLeftOpen aria-hidden size={20} className="hidden flex-none [:root[data-sidebar=collapsed]_&]:block" />
        <span className="wk-nav-label">畳む</span>
      </button>
    </nav>
  );
}

"use client";

/**
 * 選んだテーマのフォントを Google Fonts から読み込む（グラファイトは next/font で読み込み済みなので何もしない）。
 * 届くまでは端末の日本語フォントで表示され、届いたら差し替わる。
 */
import { PALETTES } from "@/lib/palettes";
import { usePalette } from "@/lib/prefs";

export function ThemeFonts() {
  const id = usePalette();
  const p = id === "graphite" ? null : PALETTES.find((x) => x.id === id);
  return p ? <link rel="stylesheet" href={p.href} /> : null;
}

"use client";

/*
 * Workspace Kit の下タブのガラスの入れ物。元は @zakisheriff/liquid-glass 4.0.3 の LensTrack（Copyright (c) 2026 Zaki Sheriff、MIT License。全文は同じフォルダの LICENSE）。
 * WK: 中の項目（リンク・ボタン）は呼ぶ側が描く。役割（tablist/tab）は付けず、下タブはリンクの並び（nav）のままにする。
 *
 *   止まっているとき … 選んだタブの下に、バーより少し灰色の薄い玉（.lg-track__select）
 *   指が触れた瞬間   … 玉が持ち上がって澄んだ泡のレンズになり、下のアイコンを拡大して色を塗る（onPress）
 *   なぞる           … レンズが指についてきて、速さに応じて伸び、止まるとぷるんと揺れる
 *   離した瞬間       … 一番近いタブへ落ちて揺れながら収まる（onSelect）
 */
import React, { useRef } from "react";
import { useLensTrack } from "./lensTrack";
import { useRefraction } from "./refraction";

export type LensTrackItemProps = {
  "data-lg-item": number;
  className: string;
};

export type LensTrackProps = {
  count: number;
  /** 選んでいる項目。-1 はどれも選ばない（玉を隠す） */
  index: number;
  /** 離した瞬間（今の項目でも呼ぶ） */
  onSelect: (index: number) => void;
  /** 触れた瞬間・なぞって別の項目に乗った瞬間 */
  onPress?: (index: number) => void;
  /** i 番目の項目を描く。渡した props（data-lg-item・className）をそのまま付ける */
  renderItem: (index: number, props: LensTrackItemProps) => React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
};

const ZOOM = 1.04;

export function LensTrack({ count, index, onSelect, onPress, renderItem, className, style }: LensTrackProps) {
  const bar = useRef<HTMLDivElement>(null);
  const glass = useRef<HTMLSpanElement>(null);
  const lens = useRef<HTMLSpanElement>(null);
  const select = useRef<HTMLSpanElement>(null);

  useRefraction(glass, { kind: "surface", strength: 1 });
  // レンズはバーの拡大した写しを映し、縁で曲げる（Chrome は本物の屈折、Safari は写しを SVG で曲げる）
  useRefraction(
    lens,
    { kind: "lens", strength: 1, stretch: 1, bezel: 24, zoom: ZOOM, dispersion: 1, copy: "refract", copyOnly: true },
    true,
    bar,
    () => bar.current?.hasAttribute("data-lifted") ?? false,
  );

  useLensTrack(
    { bar, glass, lens, select },
    {
      count,
      index: Math.max(0, index),
      onSelect,
      onPress,
      arrowKeys: false,
      overhang: 14,
      spread: 0.3,
      contentZoom: ZOOM,
      copied: true,
      // WK: スライム感を強める（元は 14）。触っている間、バー全体が横に少しふくらむ
      swell: 22,
      pull: true,
    },
  );

  return (
    <div
      ref={bar}
      className={["lg-track", "lg-track--tabbar", "lg-nav", className].filter(Boolean).join(" ")}
      data-liquid-glass=""
      data-wk-none={index < 0 ? "" : undefined}
      style={{ ...style, "--lg-count": count, "--lg-index": Math.max(0, index) } as React.CSSProperties}
    >
      <span ref={glass} className="lg-glass lg-track__glass" aria-hidden="true" />
      <span ref={select} className="lg-track__select" aria-hidden="true" />
      {Array.from({ length: count }, (_, i) => (
        <React.Fragment key={i}>{renderItem(i, { "data-lg-item": i, className: "lg-track__item" })}</React.Fragment>
      ))}
      <span ref={lens} className="lg-glass lg-track__lens" data-lg-mirror-bare="" aria-hidden="true" />
    </div>
  );
}

/*
 * Workspace Kit の下タブのガラスの動き。元は @zakisheriff/liquid-glass 4.0.3（Copyright (c) 2026 Zaki Sheriff、MIT License。全文は同じフォルダの LICENSE）。
 * Workspace Kit 用に書き換えた所には「WK:」と書いてある。
 */
/* eslint-disable react-hooks/refs, react-hooks/immutability -- WK: 元のライブラリは描画の外で DOM を直接動かす作り（毎コマ React を通さないため）。この規則はその作りと合わない */
/**
 * Shared behaviour for tab bars and segmented controls.
 *
 * At rest the selection is a flat pill. Touch it and the pill inflates into a
 * clear refracting lens that rides above the bar, follows the finger (leaning
 * and stretching with speed), magnifies and tints what passes beneath it, then
 * drops into the nearest slot with a wobble.
 */
import { useEffect, useRef } from 'react';
import { guardSelection } from './selection';
import { SPRINGS, clamp, createJelly, createSpring, prefersReducedMotion, rubberband, springFrom } from './spring';
import { haptic } from './haptics';

/** Finger-following feel for the bar's pull, as on buttons. */
const FOLLOW = springFrom(0.2, 0.82);
/** A dragged lens's stretch: looser and further than the default jelly, so a
 *  fast drag jiggles when it stops. Taps keep the standard feel. */
const WOBBLE = springFrom(0.34, 0.16);
const WOBBLE_REACH = 0.34;

export interface LensTrackRefs {
  bar: React.RefObject<HTMLElement | null>;
  lens: React.RefObject<HTMLElement | null>;
  select: React.RefObject<HTMLElement | null>;
  glass: React.RefObject<HTMLElement | null>;
}

export interface LensTrackOptions {
  count: number;
  index: number;
  onSelect: (index: number) => void;
  /** WK: 指が触れた瞬間・なぞって別のタブに乗った瞬間に呼ぶ（選択表示を待たせないため。画面の切り替えは onSelect＝離した瞬間） */
  onPress?: (index: number) => void;
  /** WK: false で矢印キーの移動を切る（下タブはリンクの並びなので、Tab と Enter で動かす） */
  arrowKeys?: boolean;
  /** How far past the bar's height the lifted lens reaches (px). */
  overhang: number;
  /** Extra width (as a fraction of a slot) the lifted lens gains. */
  spread: number;
  /** Magnification applied by the backdrop filter to the original glyphs. */
  contentZoom?: number;
  /**
   * The lens draws a magnified copy of the bar (Safari, Firefox). The real
   * glyphs then fade out beneath the lens so they don't show doubled through
   * its clear glass.
   */
  copied?: boolean;
  /** How much the whole bar swells while touched (px on its long side). */
  swell: number;
  /** Whether a vertical drag stretches the bar toward the finger. Off for a
   *  tab bar, which never moves up or down. */
  pull?: boolean;
}

export function useLensTrack(refs: LensTrackRefs, options: LensTrackOptions) {
  const latest = useRef(options);
  latest.current = options;
  const api = useRef<{ setIndex: (index: number, instant?: boolean) => void } | null>(null);

  useEffect(() => {
    const bar = refs.bar.current;
    const lens = refs.lens.current;
    const glass = refs.glass.current;
    const select = refs.select.current;
    if (!bar || !lens || !glass || !select) return;

    // The swell and pull move the whole component. A bar that is the only
    // thing inside a glass shell (a dock that frosts the page for it) moves
    // with that shell; otherwise its own glass would stay put while the
    // icons and labels moved.
    const parent = bar.parentElement;
    const shell = parent?.classList.contains('lg-glass') && parent.childElementCount === 1 ? parent : bar;

    let slot = 0;
    let height = 0;
    let pad = 0;
    let padY = 0;
    // The lens is laid out at its full lifted size (W×H) and only scaled
    // *down* toward the resting pill. At full lift it renders 1:1: true pill
    // curves and a pixel-sharp baked rim, never a stretched bitmap.
    let W = 0;
    let H = 0;
    const state = { x: 0, lift: 0, swell: 0, squash: 0, pull: 0 };
    let current = latest.current.index;
    let gesture: {
      id: number;
      startX: number;
      startY: number;
      anchor: number;
      moved: boolean;
      box: DOMRect;
      hovered: number;
      startedAt: number;
    } | null = null;
    let dropTimer = 0;
    let suppressClick = false;
    // Direct children only: a copied lens (Safari) holds inert clones of them.
    const buttons = Array.from(bar.querySelectorAll<HTMLElement>(':scope > [data-lg-item]'));
    let glyphs: Array<{ node: HTMLElement; x: number; y: number; width: number; height: number; label: boolean; host: HTMLElement; dx: number; dy: number }> = [];
    const preview = (index?: number) => {
      if (index === undefined) delete bar.dataset.previewing;
      else bar.dataset.previewing = '';
      buttons.forEach((button, i) => button.toggleAttribute('data-lg-preview', i === index));
    };

    const measure = () => {
      const style = getComputedStyle(bar);
      pad = parseFloat(style.paddingLeft) || 0;
      padY = parseFloat(style.paddingTop) || 0;
      slot = (bar.clientWidth - pad - (parseFloat(style.paddingRight) || 0)) / latest.current.count;
      height = bar.clientHeight - padY - (parseFloat(style.paddingBottom) || 0);
      const { overhang, spread } = latest.current;
      H = Math.round(bar.offsetHeight + overhang);
      // Give narrow segments the same lifted clearance at their sides as
      // above/below. A percentage alone leaves short labels tightly boxed.
      W = Math.round(Math.max(slot * (1 + spread), slot + H - height));
      lens.style.width = `${W}px`;
      lens.style.height = `${H}px`;
      lens.style.left = `${pad + (slot - W) / 2}px`;
      lens.style.top = `${padY + (height - H) / 2}px`;
      select.style.width = `${slot}px`;
      select.style.left = `${pad}px`;
      glyphs = buttons.flatMap((button) =>
        Array.from(button.querySelectorAll<HTMLElement>('.lg-nav__label, .lg-nav__icon')).map((box) => {
          // Symbols are already masked to their shape, so their hide mask
          // goes on the icon box around them. Any other icon (an SVG, an
          // image) is measured and masked by its box.
          const label = box.classList.contains('lg-nav__label');
          const node = label ? box : (box.querySelector<HTMLElement>(':scope > .lg-symbol') ?? box);
          const host = box;
          const n = node.getBoundingClientRect();
          const h = host.getBoundingClientRect();
          return {
            node,
            x: button.offsetLeft + node.offsetLeft - pad,
            y: node.offsetTop,
            width: node.offsetWidth,
            height: node.offsetHeight,
            label,
            host,
            dx: n.left - h.left,
            dy: n.top - h.top,
          };
        }),
      );
    };

    const paint = () => {
      const { swell, squash } = state;
      const x = state.x;
      const lift = clamp(state.lift, 0, 1.08);
      if (!W || !H) return;
      const kx = ((slot + (W - slot) * lift) / W) * (1 + squash);
      const ky = ((height + (H - height) * lift) / H) * (1 - squash * 0.6);
      const grow = 1 + (latest.current.swell / Math.max(bar.offsetWidth, 1)) * swell;
      // The bar is held by the finger like a button, but only vertically:
      // sideways drags move the lens, never the bar. Pulled up or down it
      // leans a few px and draws out a little that way, thinning across.
      const pull = state.pull;
      const ey = Math.abs(pull) / Math.max(bar.offsetHeight, 1);
      const transform = `translateX(${x}px) scale(${kx}, ${ky})`;
      lens.style.transform = transform;
      select.style.transform = `translateX(${x}px)`;
      lens.style.opacity = String(clamp(lift * 4, 0, 1));
      // A bar that doesn't pull only swells sideways: it never moves up or down.
      shell.style.scale = latest.current.pull === false ? `${grow} 1` : `${grow * (1 - ey * 0.15)} ${grow * (1 + ey * 0.5)}`;
      shell.style.translate = `0px ${pull / 2}px`;
      lens.style.setProperty('--lg-lift', String(clamp(lift, 0, 1)));
      bar.style.setProperty('--lg-lift', String(clamp(lift, 0, 1)));
      // Paint a true capsule over each original glyph. A single horizontal
      // gradient turns an icon blue in a rectangular strip before the curved
      // end reaches it. Account for the filter's source magnification too.
      for (const glyph of glyphs) {
        if (lift <= 0.02 && !gesture) {
          glyph.node.style.removeProperty('--lg-content-tint');
          glyph.node.style.removeProperty('transform');
          glyph.host.style.removeProperty('--lg-content-hide');
          continue;
        }
        if (latest.current.copied) {
          // Cut the lens's true footprint out of the real glyph.
          const hy = H * ky / 2;
          const hx = H * kx / 2;
          const run = Math.max(0, (W - H) * kx / 2);
          const ccx = x + slot / 2 - glyph.x + glyph.dx;
          const ccy = height / 2 - glyph.y + glyph.dy;
          const fade = clamp(lift * 3, 0, 1);
          const solid = `rgb(0 0 0 / ${fade})`;
          glyph.host.style.setProperty('--lg-content-hide', [
            'linear-gradient(#000, #000)',
            `radial-gradient(ellipse ${hx}px ${hy}px at ${ccx - run}px ${ccy}px, ${solid} calc(100% - 1px), transparent 100%)`,
            `radial-gradient(ellipse ${hx}px ${hy}px at ${ccx + run}px ${ccy}px, ${solid} calc(100% - 1px), transparent 100%)`,
            `linear-gradient(${solid}, ${solid}) ${ccx - run}px ${ccy - hy}px / ${run * 2}px ${hy * 2}px no-repeat`,
          ].join(', '));
        }
        const zoom = latest.current.contentZoom ?? 1;
        const ry = H * ky / (2 * zoom);
        const rx = H * kx / (2 * zoom);
        const straight = Math.max(0, (W - H) * kx / (2 * zoom));
        const dy = clamp(Math.abs(glyph.y + glyph.height / 2 - height / 2) / ry, 0, 1);
        const half = straight + rx * Math.sqrt(1 - dy * dy);
        const from = x + slot / 2 - half - glyph.x;
        const to = x + slot / 2 + half - glyph.x;
        const normal = 'var(--lg-fg)';
        const active = 'var(--lg-track-active, var(--lg-accent))';
        const coverage = clamp((Math.min(glyph.width, to) - Math.max(0, from)) / Math.max(1, glyph.width), 0, 1);
        const scale = 1 + clamp(lift, 0, 1) * coverage * (glyph.label ? 0.035 : 0.08);
        const cx = (x + slot / 2 - glyph.x - glyph.width / 2) / scale + glyph.width / 2;
        const cy = (height / 2 - glyph.y - glyph.height / 2) / scale + glyph.height / 2;
        const left = cx - straight / scale;
        const right = cx + straight / scale;
        const radiusX = rx / scale;
        const radiusY = ry / scale;
        glyph.node.style.setProperty('--lg-content-tint', [
          `radial-gradient(ellipse ${radiusX}px ${radiusY}px at ${left}px ${cy}px, ${active} calc(100% - 0.5px), transparent 100%)`,
          `radial-gradient(ellipse ${radiusX}px ${radiusY}px at ${right}px ${cy}px, ${active} calc(100% - 0.5px), transparent 100%)`,
          `linear-gradient(${active}, ${active}) ${left}px ${cy - radiusY}px / ${right - left}px ${radiusY * 2}px no-repeat`,
          `linear-gradient(${normal}, ${normal})`,
        ].join(', '));
        glyph.node.style.transform = `scale(${scale})`;
      }
      if (!gesture && lift < 0.02) delete bar.dataset.lifted;
    };

    // Travel stretches the droplet along its path, more the faster it goes,
    // and it jiggles back to round when the drag slows or stops.
    // Set while a drag moves the lens (and until it lands): only then does
    // it get the looser wobble.
    let dragging = false;
    const jelly = createJelly((value) => {
      state.squash = value;
      paint();
    }, 0.13, 1600);
    const x = createSpring(current * slot, SPRINGS.snap, (value, velocity) => {
      state.x = value;
      jelly.feed(velocity, dragging ? WOBBLE_REACH : undefined);
      paint();
    });
    const lift = createSpring(0, SPRINGS.lift, (value) => {
      state.lift = value;
      paint();
    });
    const swell = createSpring(0, SPRINGS.press, (value) => {
      state.swell = value;
      paint();
    });
    const pullY = createSpring(0, SPRINGS.release, (value) => {
      state.pull = value;
      paint();
    });
    const pull = (dy: number) => {
      if (latest.current.pull === false) return;
      // Saturating reach (rubber band): a long drag barely adds to it, so the
      // bar gives like a droplet held in place and never slides away.
      pullY.tune(FOLLOW);
      pullY.set(rubberband(dy, Math.min(22, bar.offsetHeight * 0.4), 0.5));
    };
    const letGo = () => {
      pullY.tune(SPRINGS.release);
      pullY.set(0);
    };

    const place = (index: number, instant = false) => {
      current = index;
      if (!gesture) {
        x.tune(SPRINGS.snap);
        x.set(index * slot, instant);
      }
    };

    const position = (clientX: number) => {
      if (!gesture) return 0;
      const raw = gesture.anchor + (clientX - gesture.startX) * bar.offsetWidth / Math.max(1, gesture.box.width);
      const max = slot * (latest.current.count - 1);
      // iOS gives only a few points of overscroll past the end segments.
      const give = Math.min(14, slot * 0.12);
      if (raw < 0) return rubberband(raw, give, 0.55);
      if (raw > max) return max + rubberband(raw - max, give, 0.55);
      return raw;
    };

    const light = (clientX: number, box: DOMRect) => {
      glass.style.setProperty('--lg-x', `${clamp(((clientX - box.left) / box.width) * 100, 0, 100)}%`);
      lens.style.setProperty('--lg-x', `${clamp(((clientX - box.left - pad - state.x) / slot) * 100, 0, 100)}%`);
    };

    const itemAt = (event: PointerEvent) => {
      const target = (event.target as HTMLElement).closest<HTMLElement>('[data-lg-item]');
      return target && bar.contains(target) ? Number(target.dataset.lgItem) : -1;
    };

    const onDown = (event: PointerEvent) => {
      delete bar.dataset.keyboard;
      if (!event.isPrimary || event.button !== 0 || gesture) return;
      const index = itemAt(event);
      if (index < 0) return;
      clearTimeout(dropTimer);
      measure();
      dragging = false;
      jelly.tune(SPRINGS.jelly);
      const box = bar.getBoundingClientRect();
      gesture = { id: event.pointerId, startX: event.clientX, startY: event.clientY, anchor: index * slot, moved: false, box, hovered: index, startedAt: performance.now() };
      suppressClick = false;
      // WK: 動きを減らす設定では、レンズを持ち上げず、バーもふくらませない（選んだ玉がすぐ移るだけ）
      const still = prefersReducedMotion();
      if (!still) bar.dataset.lifted = '';
      preview(index);
      latest.current.onPress?.(index);
      lens.dataset.pressed = '';
      light(event.clientX, box);
      haptic();
      lift.tune(SPRINGS.lift);
      lift.set(still ? 0 : 1);
      swell.tune(SPRINGS.press);
      swell.set(still ? 0 : 1);
      // The lens slides out of the old selection toward the finger.
      x.tune(SPRINGS.snap);
      x.set(index * slot);
      paint();
    };

    const onMove = (event: PointerEvent) => {
      if (event.pointerId !== gesture?.id) return;
      if (!gesture.moved && Math.abs(event.clientX - gesture.startX) > 5) {
        gesture.moved = true;
        try {
          bar.setPointerCapture(event.pointerId);
        } catch {
          /* already released */
        }
      }
      light(event.clientX, gesture.box);
      pull(event.clientY - gesture.startY);
      if (!gesture.moved) return;
      const at = position(event.clientX);
      if (!dragging) {
        dragging = true;
        jelly.tune(WOBBLE);
      }
      x.tune(SPRINGS.drag);
      x.set(at);
      const hovered = clamp(Math.round(at / slot), 0, latest.current.count - 1);
      if (hovered !== gesture.hovered) {
        gesture.hovered = hovered;
        preview(hovered);
        latest.current.onPress?.(hovered);
        haptic();
      }
    };

    const finish = (event: PointerEvent, commit: boolean) => {
      if (event.pointerId !== gesture?.id) return;
      const { moved, box, startedAt } = gesture;
      const at = moved ? position(event.clientX) : gesture.anchor;
      const index = clamp(Math.round(at / slot), 0, latest.current.count - 1);
      gesture = null;
      preview();
      delete lens.dataset.pressed;
      if (bar.hasPointerCapture?.(event.pointerId)) bar.releasePointerCapture(event.pointerId);
      const inside = event.clientY >= box.top - 30 && event.clientY <= box.bottom + 30;
      // A quick tap should show the full lift, just like holding the tab.
      // Drags still settle immediately when the pointer is released.
      const drop = () => {
        lift.tune(SPRINGS.settle);
        lift.set(0);
      };
      const hold = commit && !moved ? Math.max(0, 200 - (performance.now() - startedAt)) : 0;
      if (hold) dropTimer = window.setTimeout(drop, hold);
      else drop();
      swell.tune(SPRINGS.release);
      swell.set(0);
      letGo();
      x.tune(SPRINGS.snap);
      if (commit && (moved || inside)) {
        suppressClick = true;
        current = index;
        x.set(index * slot);
        // WK: 今のタブでも呼ぶ（「その他」は今いる場所でも開き直せるように。同じ画面への移動は呼ぶ側で省く）
        latest.current.onSelect(index);
      } else {
        x.set(current * slot);
      }
    };

    const onUp = (event: PointerEvent) => finish(event, true);
    const onCancel = (event: PointerEvent) => finish(event, false);
    const onBlur = () => {
      clearTimeout(dropTimer);
      if (!gesture) {
        lift.tune(SPRINGS.settle);
        lift.set(0);
        return;
      }
      const id = gesture.id;
      gesture = null;
      preview();
      delete lens.dataset.pressed;
      if (bar.hasPointerCapture(id)) bar.releasePointerCapture(id);
      lift.tune(SPRINGS.settle);
      lift.set(0);
      swell.tune(SPRINGS.release);
      swell.set(0);
      letGo();
      x.tune(SPRINGS.snap);
      x.set(current * slot);
    };

    const onClick = (event: MouseEvent) => {
      if (suppressClick && event.detail !== 0) {
        suppressClick = false;
        event.preventDefault();
        event.stopPropagation();
        return;
      }
      const target = (event.target as HTMLElement).closest<HTMLElement>('[data-lg-item]');
      if (!target) return;
      const index = Number(target.dataset.lgItem);
      latest.current.onSelect(index); // WK: 上と同じく今のタブでも呼ぶ
    };

    const onKey = (event: KeyboardEvent) => {
      const keys = ['ArrowLeft', 'ArrowRight', 'Home', 'End'];
      if (latest.current.arrowKeys === false || !keys.includes(event.key)) return;
      bar.dataset.keyboard = '';
      event.preventDefault();
      const { count, index } = latest.current;
      const next =
        event.key === 'Home'
          ? 0
          : event.key === 'End'
            ? count - 1
            : (index + (event.key === 'ArrowRight' ? 1 : count - 1)) % count;
      latest.current.onSelect(next);
      bar.querySelector<HTMLElement>(`[data-lg-item="${next}"]`)?.focus();
    };

    const onTouchMove = (event: TouchEvent) => {
      // Holding the lens owns the gesture: the page must not scroll under it.
      if (gesture && event.cancelable) event.preventDefault();
    };

    const observer = new ResizeObserver(() => {
      measure();
      if (!gesture) x.set(current * slot, true);
    });

    measure();
    x.set(current * slot, true);
    bar.dataset.ready = '';
    observer.observe(bar);
    const unguard = guardSelection(bar);
    bar.addEventListener('pointerdown', onDown);
    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onCancel);
    window.addEventListener('blur', onBlur);
    bar.addEventListener('click', onClick, true);
    bar.addEventListener('keydown', onKey);
    bar.addEventListener('touchmove', onTouchMove, { passive: false });

    api.current = { setIndex: place };

    return () => {
      clearTimeout(dropTimer);
      api.current = null;
      [x, lift, swell, pullY, jelly].forEach((s) => s.stop());
      shell.style.removeProperty('scale');
      shell.style.removeProperty('translate');
      unguard();
      observer.disconnect();
      bar.removeEventListener('pointerdown', onDown);
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onCancel);
      window.removeEventListener('blur', onBlur);
      bar.removeEventListener('click', onClick, true);
      bar.removeEventListener('keydown', onKey);
      bar.removeEventListener('touchmove', onTouchMove);
      delete bar.dataset.ready;
      delete bar.dataset.lifted;
      preview();
      glyphs.forEach(({ node, host }) => {
        node.style.removeProperty('--lg-content-tint');
        node.style.removeProperty('transform');
        host.style.removeProperty('--lg-content-hide');
      });
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [options.count]);

  useEffect(() => {
    api.current?.setIndex(options.index);
  }, [options.index]);
}

