/**
 * Keeps refraction affordable.
 *
 * A refracting surface re-runs its SVG displacement over the live backdrop on
 * every frame the backdrop moves. Fast GPUs shrug that off; mid-range phones
 * drop frames as soon as a page holds a few dozen of them. So:
 *
 * - while the page scrolls, `html[data-lg-scrolling]` turns refraction off
 *   (blur and the baked rim stay, which reads the same in motion);
 * - glass well outside the viewport gets `data-lg-offscreen` and skips it;
 * - on weak devices (`html[data-lg-quality='low']`) resting surfaces keep blur
 *   and rim only; lenses still bend while they're held.
 *
 * The quality starts from device hints and drops to low if the first seconds
 * of scrolling miss frames. `setGlassQuality` pins it either way.
 */

export type GlassQuality = 'auto' | 'high' | 'low';

let started = false;
let pinned: GlassQuality = 'auto';
let probing = false;
let offscreen: IntersectionObserver | null = null;

const root = () => document.documentElement;

function apply(level: 'high' | 'low') {
  if (root().getAttribute('data-lg-quality') !== level) root().setAttribute('data-lg-quality', level);
}

/** Device hints: few cores or little memory (Chromium reports both). */
function guess(): 'high' | 'low' {
  const nav = navigator as Navigator & { deviceMemory?: number };
  if (typeof nav.deviceMemory === 'number' && nav.deviceMemory <= 4) return 'low';
  if (typeof nav.hardwareConcurrency === 'number' && nav.hardwareConcurrency <= 4) return 'low';
  return 'high';
}

/**
 * Times frames while the page scrolls with refraction paused and resumed.
 * If too many miss the frame budget the device can't carry it: go low.
 */
function probe() {
  if (probing || pinned !== 'auto' || root().getAttribute('data-lg-quality') === 'low') return;
  probing = true;
  const gaps: number[] = [];
  let last = 0;
  let frame = 0;
  const end = performance.now() + 2000;
  const step = (now: number) => {
    if (last) gaps.push(now - last);
    last = now;
    if (now < end && gaps.length < 120) {
      frame = requestAnimationFrame(step);
      return;
    }
    probing = false;
    if (gaps.length < 20 || pinned !== 'auto') return;
    const slow = gaps.filter((gap) => gap > 26).length / gaps.length;
    if (slow > 0.2) apply('low');
  };
  frame = requestAnimationFrame(step);
  void frame;
}

function watchScroll() {
  let timer = 0;
  let probes = 0;
  const settle = () => {
    timer = 0;
    root().removeAttribute('data-lg-scrolling');
  };
  const onScroll = () => {
    if (!timer) {
      root().setAttribute('data-lg-scrolling', '');
      // Sample the first couple of scrolls after load: that's when a page
      // full of glass is most expensive.
      if (probes < 2) {
        probes++;
        probe();
      }
    } else {
      clearTimeout(timer);
    }
    timer = window.setTimeout(settle, 140);
  };
  // Capture: nested scrollers (sheets, panels) count too.
  document.addEventListener('scroll', onScroll, { capture: true, passive: true });
}

function start() {
  if (started || typeof window === 'undefined') return;
  started = true;
  apply(pinned === 'auto' ? guess() : pinned);
  watchScroll();
  if (typeof IntersectionObserver === 'function') {
    offscreen = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          const el = entry.target as HTMLElement;
          if (entry.isIntersecting) el.removeAttribute('data-lg-offscreen');
          else el.setAttribute('data-lg-offscreen', '');
        }
      },
      // Turn back on a little before it scrolls into view.
      { rootMargin: '25% 0px' },
    );
  }
}

/** Starts the governor and tracks `element`'s visibility. Returns a cleanup. */
export function governRefraction(element: HTMLElement): () => void {
  start();
  offscreen?.observe(element);
  return () => {
    offscreen?.unobserve(element);
    element.removeAttribute('data-lg-offscreen');
  };
}

/**
 * Pins the refraction quality. `'auto'` (default) picks from device hints and
 * drops to `'low'` if scrolling misses frames; `'high'` always refracts
 * resting surfaces; `'low'` refracts lenses only while they're held.
 */
export function setGlassQuality(quality: GlassQuality) {
  pinned = quality;
  if (typeof window === 'undefined') return;
  if (!started) start();
  apply(quality === 'auto' ? guess() : quality);
}

/*
 * Workspace Kit の下タブのガラスの動き。元は @zakisheriff/liquid-glass 4.0.3（Copyright (c) 2026 Zaki Sheriff、MIT License。全文は同じフォルダの LICENSE）。
 * Workspace Kit 用に書き換えた所には「WK:」と書いてある。
 */
/**
 * Closed-form damped harmonic springs, stepped on a shared rAF loop.
 *
 * Each spring is solved analytically per frame (no Euler drift), so stiff
 * presses stay stable and soft releases wobble exactly as tuned.
 */

export interface SpringConfig {
  /** Spring constant k (mass is 1). */
  stiffness: number;
  /** Damping coefficient c. ζ = c / (2√k); below 1 it overshoots. */
  damping: number;
}

export interface Spring {
  readonly value: number;
  readonly velocity: number;
  readonly target: number;
  /** Animate toward `target`. `instant` jumps there. */
  set(target: number, instant?: boolean): void;
  /** Change the feel mid-flight without losing velocity. */
  tune(config: SpringConfig): void;
  /** Give the spring a kick (px/s or units/s). */
  impulse(velocity: number): void;
  stop(): void;
}

interface State {
  value: number;
  target: number;
  velocity: number;
  k: number;
  c: number;
  onUpdate: (value: number, velocity: number) => void;
}

const active = new Set<State>();
let frame = 0;
let last = 0;

function step(s: State, dt: number) {
  const x = s.value - s.target;
  const v = s.velocity;
  const half = s.c / 2;
  const disc = half * half - s.k;

  if (Math.abs(disc) < 1e-6) {
    // Critically damped
    const decay = Math.exp(-half * dt);
    const b = v + half * x;
    s.value = s.target + decay * (x + b * dt);
    s.velocity = decay * (v - half * b * dt);
  } else if (disc > 0) {
    // Overdamped
    const root = Math.sqrt(disc);
    const r1 = -half + root;
    const r2 = -half - root;
    const a = (v - r2 * x) / (r1 - r2);
    const b = x - a;
    const e1 = Math.exp(r1 * dt);
    const e2 = Math.exp(r2 * dt);
    s.value = s.target + a * e1 + b * e2;
    s.velocity = a * r1 * e1 + b * r2 * e2;
  } else {
    // Underdamped: the jiggle
    const w = Math.sqrt(-disc);
    const decay = Math.exp(-half * dt);
    const cos = Math.cos(w * dt);
    const sin = Math.sin(w * dt);
    s.value = s.target + decay * (x * cos + ((v + half * x) / w) * sin);
    s.velocity = decay * (v * cos - ((half * v + s.k * x) / w) * sin);
  }
}

function loop(time: number) {
  frame = 0;
  const dt = Math.min(0.064, Math.max(0, (time - last) / 1000));
  last = time;
  // A snapshot: an update may wake another spring (a drag feeding its
  // jelly), which must wait for the next frame rather than be revisited.
  for (const s of [...active]) {
    step(s, dt);
    if (Math.abs(s.value - s.target) < 1e-4 && Math.abs(s.velocity) < 1e-3) {
      s.value = s.target;
      s.velocity = 0;
      active.delete(s);
    }
    s.onUpdate(s.value, s.velocity);
  }
  // A spring woken during this pass has already queued the next frame;
  // queueing another would double the loop every frame.
  if (active.size && !frame) frame = requestAnimationFrame(loop);
}

function wake() {
  if (frame) return;
  last = performance.now();
  frame = requestAnimationFrame(loop);
}

export function prefersReducedMotion(): boolean {
  return typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
}

export function createSpring(
  initial: number,
  config: SpringConfig,
  onUpdate: (value: number, velocity: number) => void,
): Spring {
  const s: State = {
    value: initial,
    target: initial,
    velocity: 0,
    k: config.stiffness,
    c: config.damping,
    onUpdate,
  };

  return {
    get value() {
      return s.value;
    },
    get velocity() {
      return s.velocity;
    },
    get target() {
      return s.target;
    },
    set(target, instant = false) {
      s.target = target;
      if (instant || prefersReducedMotion() || (typeof document !== 'undefined' && document.hidden)) {
        s.value = target;
        s.velocity = 0;
        active.delete(s);
        onUpdate(s.value, 0);
        return;
      }
      active.add(s);
      wake();
    },
    tune(next) {
      s.k = next.stiffness;
      s.c = next.damping;
    },
    impulse(velocity) {
      s.velocity += velocity;
      active.add(s);
      wake();
    },
    stop() {
      active.delete(s);
    },
  };
}

/** Converts Apple-style (response, dampingFraction) into k/c. */
export function springFrom(response: number, dampingFraction: number): SpringConfig {
  const w = (2 * Math.PI) / response;
  return { stiffness: w * w, damping: 2 * dampingFraction * w };
}

/** Feel presets, tuned by eye against iOS 26 screen recordings. */
export const SPRINGS = {
  /** Finger down: quick, almost no overshoot. */
  press: springFrom(0.22, 0.86),
  /** Finger up: soft settle with the gentle jelly wobble. */
  release: springFrom(0.42, 0.5),
  /** Following the finger during a drag. */
  drag: springFrom(0.12, 0.92),
  /** Sliding into a new slot after release. */
  snap: springFrom(0.36, 0.72),
  /** Lens inflating out of a selection pill. */
  lift: springFrom(0.26, 0.78),
  /** Lens deflating back into a pill: visibly wobbly. */
  settle: springFrom(0.45, 0.46),
  /** Colour cross-fades. */
  fade: springFrom(0.3, 1),
  /** A dragged lens's stretch: loose, so it wobbles when the drag stops. */
  jelly: springFrom(0.3, 0.3),
} as const;

/**
 * Speed-driven stretch for a dragged droplet. Feed it the travel velocity
 * every frame: the faster the drag the more it stretches (easing off so a
 * flick never smears it), and when the motion slows or stops the stretch
 * springs back past round and wobbles once or twice before it settles.
 * The value is positive when stretched along the path, negative when the
 * rebound briefly makes it narrower and taller.
 */
export function createJelly(onUpdate: (stretch: number) => void, max: number, speed: number) {
  const spring = createSpring(0, SPRINGS.jelly, (value) => onUpdate(value));
  return {
    feed(velocity: number, reach = max) {
      spring.set(reach * Math.tanh(Math.abs(velocity) / speed));
    },
    tune(next: SpringConfig) {
      spring.tune(next);
    },
    stop() {
      spring.stop();
    },
  };
}

/** iOS-style rubber banding for overscroll. */
export function rubberband(offset: number, dimension: number, constant = 0.55): number {
  const sign = Math.sign(offset);
  const x = Math.abs(offset);
  return sign * (1 - 1 / ((x * constant) / dimension + 1)) * dimension;
}

export const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

